use xiom.io;

type Rectangle = {
  width: Float64;
  height: Float64;
}

fn Rectangle.area(self) -> Float64 {
  return width * height;
}

fn Rectangle.perimeter(self) -> Float64 {
  return 2.0 * (width + height);
}

fn main() -> Int {
  let rect = Rectangle{ width: 7.0, height: 3.0 };
  io.println(rect.area().to_str());
  io.println(rect.perimeter().to_str());
  return 0;
}
